import { useState, useEffect } from 'react';
import client from '../../api/client';

const empty = { nombreProducto:'', tipo:'agotado', cantidad:'', observacion:'' };

const estadoBadge = { pendiente:'badge-yellow', resuelto:'badge-green', descartado:'badge-gray' };

export default function Faltantes() {
  const [faltantes, setFaltantes] = useState([]);
  const [form, setForm]           = useState(empty);
  const [showForm, setShowForm]   = useState(false);
  const [filtro, setFiltro]       = useState('pendiente');
  const [loading, setLoading]     = useState(false);

  useEffect(() => { cargar(); }, [filtro]);

  const cargar = async () => {
    const { data } = await client.get(`/api/faltantes${filtro ? `?estado=${filtro}` : ''}`);
    setFaltantes(data);
  };

  const guardar = async (e) => {
    e.preventDefault(); setLoading(true);
    try {
      await client.post('/api/faltantes', { ...form, cantidad: parseInt(form.cantidad) || null });
      setShowForm(false); setForm(empty); cargar();
    } catch (err) { alert(err.response?.data?.error || 'Error'); }
    finally { setLoading(false); }
  };

  const cambiarEstado = async (id, estado) => {
    await client.patch(`/api/faltantes/${id}/estado`, { estado });
    cargar();
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">⚠️ Faltantes</h1>
        <button className="btn btn-primary" onClick={() => setShowForm(true)}>+ Registrar faltante</button>
      </div>

      <div className="card" style={{ marginBottom:16, display:'flex', gap:10, flexWrap:'wrap' }}>
        {['', 'pendiente', 'resuelto', 'descartado'].map(e => (
          <button key={e} className={`btn ${filtro === e ? 'btn-primary' : 'btn-secondary'}`}
            onClick={() => setFiltro(e)}>
            {e === '' ? 'Todos' : e.charAt(0).toUpperCase() + e.slice(1)}
          </button>
        ))}
      </div>

      <div className="card table-wrap">
        <table>
          <thead><tr><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Observación</th><th>Estado</th><th>Fecha</th><th>Acciones</th></tr></thead>
          <tbody>
            {faltantes.map(f => (
              <tr key={f.id}>
                <td><strong>{f.nombreProducto}</strong></td>
                <td><span className={`badge ${f.tipo === 'agotado' ? 'badge-red' : 'badge-blue'}`}>{f.tipo}</span></td>
                <td>{f.cantidad || '—'}</td>
                <td style={{ maxWidth:180, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{f.observacion || '—'}</td>
                <td><span className={`badge ${estadoBadge[f.estado]}`}>{f.estado}</span></td>
                <td>{new Date(f.createdAt).toLocaleDateString('es-CO')}</td>
                <td>
                  {f.estado === 'pendiente' && (
                    <div style={{ display:'flex', gap:6 }}>
                      <button className="btn btn-success" style={{ padding:'4px 8px', fontSize:'.76rem' }}
                        onClick={() => cambiarEstado(f.id, 'resuelto')}>✓ Resuelto</button>
                      <button className="btn btn-secondary" style={{ padding:'4px 8px', fontSize:'.76rem' }}
                        onClick={() => cambiarEstado(f.id, 'descartado')}>Descartar</button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div className="modal-overlay">
          <div className="modal-box">
            <h3>Registrar faltante</h3>
            <form onSubmit={guardar} style={{ marginTop:16, display:'flex', flexDirection:'column', gap:12 }}>
              <div className="field"><label>Producto *</label>
                <input required value={form.nombreProducto} onChange={e => setForm({ ...form, nombreProducto: e.target.value })} />
              </div>
              <div className="field"><label>Tipo</label>
                <select value={form.tipo} onChange={e => setForm({ ...form, tipo: e.target.value })}>
                  <option value="agotado">Agotado</option>
                  <option value="no_registrado">No registrado</option>
                </select>
              </div>
              <div className="field"><label>Cantidad aproximada</label>
                <input type="number" min="1" value={form.cantidad} onChange={e => setForm({ ...form, cantidad: e.target.value })} />
              </div>
              <div className="field"><label>Observación</label>
                <textarea rows={2} value={form.observacion} onChange={e => setForm({ ...form, observacion: e.target.value })} />
              </div>
              <div style={{ display:'flex', gap:10, justifyContent:'flex-end', marginTop:8 }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowForm(false)}>Cancelar</button>
                <button type="submit" className="btn btn-primary" disabled={loading}>{loading ? 'Guardando...' : 'Guardar'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
